typedef struct PcNativeThunk { /* as generated (pc_native_thunks.c) and in gs_asm_host.c */
    void* native;
    u32 (*thunk)(const u32* i, const float* f);
} PcNativeThunk;
extern const PcNativeThunk pc_native_thunks[]; /* generated: tools/local/port/nativethunks.py */
extern const unsigned pc_native_thunk_count;
void pc_cms_set_thunks(const PcNativeThunk* table, unsigned count);

/* ORRE_DUMP_FLAGS=1 (the story-progress meter, 2026-10-16): the game's three flag buffers (the ones GSflagInit,
 * fn_801909A8, registers: save sections 4 / 5 / 6) written to flags_end.bin in the working folder as raw big-endian
 * u32 words, class 1, then 2, then 3, the layout tools/local/colo/savefile.py already reads from a save. Written
 * every 600 game frames (through a temporary file and a rename, so a run killed by saferun's time limit still leaves
 * the last complete dump), at a normal exit, and after a crash or watchdog report. */
typedef struct {
    u32 wordCount;
    u32 buffer; /* 32-bit slot (PTR32_FIELD in gs_flag_exact_801908D4.c): an address below 4 GB */
} PcFlagState;
extern PcFlagState* lbl_80478EEC; /* GSflag's state array, [0] unused */
extern void (*pc_vi_frame_hook)(unsigned frame);
extern void pc_vi_set_close_ends_program(int on);
extern int pc_vi_virtual_clock(void); /* pc_vi.c: the deterministic replay clock */
extern void pc_card_timing_set_task(void* const* task); /* pc_card_timing.c */
extern void* _memcardStatusPtr;                              /* memcard.c: the memcard task (MemcardTaskState*) */
extern void (*pc_crash_report_hook)(void);
/* the project's game-side hook (gs_floor.c calls it when a room starts loading). gs_floor.c has a weak definition; the
 * strong one here wins. Without it the first link's stub generator saw the weak data symbol as missing and made a
 * function stub with its name, so storing into the "hook" wrote into code (verified: a crash at start-up). */
void (*pc_room_entered_hook)(u32 room);
void pc_pad_script_room_entered(unsigned room);  /* ORRE_PAD_SCRIPT's @room+frames timing (pc_pad_script.c) */
/* OrreHook_WindowReady (observation hook, docs/port/hook-points.md): menuDaemon reports each window that finishes
 * opening; the pad script times menu presses from it (@0x2<window>+N) */
void (*OrreHook_WindowReady)(u32 windowId);
void pc_pad_script_window_ready(unsigned id);
/* The event log's observation hooks (docs/port/hook-points.md; pc_event_log.c attaches them when the log is on):
 * a battle message opening (win_msg), a message's expanded text measured (gs_msg's GSmsgGetRect), a story flag
 * changing (gs_range_8018FE30's flagSetValue). Strong definitions here, in an object that is always linked. */
void (*OrreHook_BattleMessage)(u32 message);
void (*OrreHook_MessageMeasured)(u32 key, const unsigned short* chars, u32 count);
void (*OrreHook_FlagChanged)(int flagId, u32 oldValue, u32 newValue);
void (*OrreHook_TalkStarted)(u32 group, u32 id); /* hero_move.c: the person an A press talks to */
/* people.c std054_characterTalk: who says a field message (person, character-name record, its name message) */
void (*OrreHook_CharacterTalk)(u32 group, u32 id, u32 message, u32 nameRecord, u32 nameMessage);
void pc_event_log_install(void); /* pc_event_log.c */
void pc_event_log_room(u32 room);
/* OrreHook_OldCryIndex (a replay-compatibility hook, docs/port/hook-points.md, 2026-11-10): non-zero makes the
 * cry lookup read its index the old, wrong way (before port-gaps 60's fix), so the P★DA's cry screen closes at once
 * as it did in the exe the reference playthrough's P02 was played on; that sitting then replays exactly on newer exes. NULL (the
 * default) = the fixed, console behaviour. Set only by ORRE_REPLAY_COMPAT=cry60, for replays of recordings made
 * before the fix. */
int (*OrreHook_OldCryIndex)(void);
static int old_cry_index_on(void) { return 1; }
void pc_frame_times_init(void);                   /* ORRE_REPLAY_FRAMES: the console's frame lengths (pc_frame_times.c) */
void pc_frame_times_room_entered(unsigned room);
void pc_debug_room_entered(unsigned room);       /* a checkpoint load waits for the title room (pc_debug.c) */
void pc_debug_sound_group_pushed(unsigned gid);  /* ... and for the title's sound groups (pc_debug.c) */
void pc_debug_set_build_stamp(const char* stamp); /* the F1 menu's header (pc_debug.c) */
#ifdef _WIN32
/* Ask NVIDIA's and AMD's drivers for the discrete GPU on hybrid systems (laptops mostly; the drivers read these
 * exported names from the executable). Desktop GPU choice is settings.ini "gpu" (pc_platform.c, Aurora). */
__declspec(dllexport) unsigned long NvOptimusEnablement = 1;
__declspec(dllexport) int AmdPowerXpressRequestHighPerformance = 1;
#endif

/* src/game/pc_debug_game.c: the golden slice's room-by-room comparison line (frame, RNG, flags CRC); prints
 * only with ORRE_SLICE_LOG=1 and observes only */
extern void pc_slice_log_room(unsigned room, unsigned frame);
void pc_smooth_room_entered(unsigned room); /* pc_smooth.c: frame smoothing's camera blend resets at a room change */
/* pc_ui_inventory.c: the 2D inventory test switch (ORRE_UI_INVENTORY=1; widescreen groundwork, 2026-11-19): set up at
 * start, and a room change starts a new list (observe only) */
void pc_ui_inventory_init(void);
void pc_ui_inventory_room_entered(unsigned room);
extern void (*pc_musyx_push_listener)(unsigned gid); /* musyx_pc_groups.c */
extern void (*pc_debug_audio_pause)(int on);         /* pc_debug.c */
extern void sndPCPauseAudio(_Bool value);            /* MusyX's PC output (hw_pc_sdl.c) */
static void audio_pause(int on) { sndPCPauseAudio(on != 0); }

static void flags_dump(void) {
    static int logged;
    FILE* f;
    u32 counts[3] = {0, 0, 0};
    int k;
    if (lbl_80478EEC == NULL) {
        return;
    }
    f = fopen("flags_end.bin.tmp", "wb");
    if (f == NULL) {
        return;
    }
    for (k = 1; k <= 3; k++) {
        const u32* words = (const u32*)(uintptr_t)lbl_80478EEC[k].buffer;
        u32 i, n = words != NULL ? lbl_80478EEC[k].wordCount : 0;
        for (i = 0; i < n; i++) {
            unsigned char be[4] = {(unsigned char)(words[i] >> 24), (unsigned char)(words[i] >> 16),
                                   (unsigned char)(words[i] >> 8), (unsigned char)words[i]};
            fwrite(be, 1, 4, f);
        }
        counts[k - 1] = n;
    }
    fclose(f);
    remove("flags_end.bin");
    rename("flags_end.bin.tmp", "flags_end.bin");
    if (!logged) {
        logged = 1;
        fprintf(stderr, "[flags] dumped %u+%u+%u words to flags_end.bin\n", counts[0], counts[1], counts[2]);
    }
}

static void flags_frame(unsigned frame) {
    if (frame % 600 == 0) {
        flags_dump();
    }
}

/* Which room the game is in, for the crash / watchdog report; the pad script's room timing gets the call too */
static u32 s_last_room = 0xFFFFFFFFu;
static void room_entered(u32 room) {
    s_last_room = room;
    pc_event_log_room(room); /* the flag log's room column */
    pc_pad_script_room_entered(room);
    pc_frame_times_room_entered(room); /* replay mode's console frame timing (ORRE_REPLAY_FRAMES, pc_frame_times.c) */
    pc_debug_room_entered(room);
    pc_slice_log_room(room, (unsigned)pc_vi_heartbeat); /* "[slice] entered ..." with ORRE_SLICE_LOG=1 (the project's) */
    pc_smooth_room_entered(room); /* frame smoothing, step (c): the camera snaps at a room change (pc_smooth.c) */
    pc_ui_inventory_room_entered(room); /* the 2D inventory: one list per room (ORRE_UI_INVENTORY=1 only) */
}

static int s_dump_flags;
/* After a crash or watchdog report (pc_crash_win32.c / _posix.c): where the game was, the flag dump, then make
 * sure everything printed is in the log file before the process ends */
static void crash_report(void) {
    fprintf(stderr, "[pc_crash] build: %s; last room 0x%X, game frame %u\n", ORRE_BUILD_STAMP, s_last_room,
            (unsigned)pc_vi_heartbeat);
    if (s_dump_flags) {
        flags_dump();
    }
    pc_log_drain();
}

int main(int argc, char** argv) {
    const char* disc = NULL;
    int i, result;
    pc_log_start(ORRE_BUILD_STAMP); /* first, so the log has everything */
    pc_crash_report_hook = crash_report;
    {
        /* a crash's minidump next to this run's log, the same name with .dmp (2026-11-22, the logging list's item 10;
         * pc_crash.h); kept and removed with its log (pc_log.c) */
        extern void pc_crash_set_dump_path(const char* utf8_path);
        extern const char* pc_log_path(void);
        const char* log = pc_log_path();
        const size_t n = log != NULL ? strlen(log) : 0;
        if (n > 4 && strcmp(log + n - 4, ".log") == 0 && n < 1500) {
            char dump[1500];
            memcpy(dump, log, n - 4);
            memcpy(dump + n - 4, ".dmp", 5);
            pc_crash_set_dump_path(dump);
        }
    }
    {
        /* only one OrrePort per install (rule R8, pc_single_instance.c): a second launch brings the first window
         * forward and exits before it touches the saves or the settings */
        extern int pc_single_instance_claim(void);
        if (!pc_single_instance_claim()) {
            pc_log_exit_clean("another OrrePort is open from this folder: it was brought forward");
            return 0;
        }
        /* "OrrePort is open", for Studio (pc_apps.c, 2026-11-23): its "Open OrrePort" link shows this window instead of
         * starting a second one, and its update line offers "Close OrrePort". The per-folder rule above still decides
         * whether this copy runs; this marker is per OrrePort folder too. Not in automated runs (a test run beside
         * the player's Studio shouldn't read as their OrrePort) */
        extern int pc_platform_automated_run(void);
        if (!pc_platform_automated_run()) pc_apps_claim(PC_APP_HUB, apps_root());
    }
    for (i = 1; i + 1 < argc; i++) {
        if (strcmp(argv[i], "--disc") == 0) {
            disc = argv[i + 1];
        }
    }
    if (disc == NULL) {
        pc_platform_search_disc(); /* the portable folder: <exe>/Colosseum/ROM/, the image with game ID GC6E01 */
    }
    if (!pc_platform_start(argc, argv, disc)) {
        /* a deliberate end, not a crash: the "No disc yet" hub's window closed, or the start-up refused the disc with
         * its message. *Fixed 2026-11-23 (snatcherLeo's update hand check):* this path had no clean-exit line, so closing the
         * no-disc hub was taken for an unexpected close at the next start (pc_log.h) */
        pc_log_exit_clean("the start-up ended (the no-disc hub was closed, or the disc was refused)");
        return 1;
    }
    pc_debug_set_build_stamp(ORRE_BUILD_STAMP); /* the F1 menu's header; also a report saved from the hub names it */
    {
        /* the RmlUi trial styled the window before it was first shown (pc_platform.c's window_created calls
         * pc_window_style_early, pc_settings_overlay.cpp; a weak reference: absent in builds without the overlay), so
         * the build-stamp title is only for builds without it; the stamp stays in the log either way. Setting it here
         * too was the "older name" snatcherLeo saw flash before the trial's title (2026-11-09). */
        extern void pc_window_style_early(void) __attribute__((weak));
        if (!pc_window_style_early) {
            pc_platform_set_title(ORRE_BUILD_STAMP);
        }
        /* the keyboard's default keys and Aurora's PADInit, before the hub: the hub's Controls screen needs the
         * keyboard's keys loaded (pc_controls.c; moved here from after the hub, 2026-11-13) */
        extern void pc_controls_init(void);
        pc_controls_init();
        /* the logs carry every setting (step 3.7, 2026-11-20; pc_settings_log.cpp): the settings file's change lines
         * say the game frame from here on (the hub's seconds before the game runs), and the start-up snapshot (display,
         * controllers, settings.ini, the tweaks, ORRE_ variables) goes in now, before the hub. All platforms */
        extern void pc_settings_set_frame_source(unsigned (*frame)(void));
        extern void pc_settings_log_snapshot(const char* when);
        pc_settings_set_frame_source(settings_frame);
        pc_settings_log_snapshot("at start");
        /* the hub (pc_hub.cpp, the hub plan's step 2): the first screen, before the game records or loads anything;
         * 0 when the window was closed there. Skipped in automated runs, so replays are untouched */
        extern int pc_hub_run(void) __attribute__((weak));
        extern void pc_window_cloak(int on) __attribute__((weak));
        if (pc_hub_run && !pc_hub_run()) {
            /* the language discs' background read (pc_region_text.cpp) is waited for before returning (
             * 2026-11-21): its std::thread was left joinable, and returning from main destroyed it, which ended every
             * close in the hub with "terminate called without an active exception" (an abnormal exit; every such log
             * since 2026-11-15 shows it). Waiting costs nothing: the read takes well under a second and is long done
             * by the time a player closes the hub. */
            extern void pc_region_text_finish(void) __attribute__((weak));
            if (pc_region_text_finish) {
                pc_region_text_finish();
            }
            pc_platform_stop();
            pc_log_exit_clean("the hub's window was closed");
            return 0;
        }
        if (pc_window_cloak) {
            pc_window_cloak(0); /* the window was invisible until the hub drew itself; visible from here in any case */
        }
        /* the game runs from here to the end of this process (Quit to hub starts a new one): Studio never closes it
         * (pc_apps.c) */
        pc_apps_game_begin(apps_root());
    }
    /* the memory card opens here, after the hub, so the save picked on the hub's Saves page is the one the game reads
     * (pc_card.c pc_card_open; the card's folder can't change once open). Weak: a build without Aurora's card
     * library has none */
    {
        extern void pc_card_open(void) __attribute__((weak));
        if (pc_card_open) {
            pc_card_open();
        }
        /* GameCube-accurate mode is fixed here for the rest of the run (2.12, pc_options.c): the save the game is about
         * to read decides it, and nothing switches it while the game runs (snatcherLeo, 2026-11-10: "users cannot change this
         * slider while in-game"). Before this, only the hub runs, which reads the current save's setting as it changes.
         * All platforms. */
        extern void pc_option_accurate_lock(void);
        pc_option_accurate_lock();
    }
    pc_pad_record_start(ORRE_BUILD_STAMP);      /* every PADRead the game makes, in the portable layout */
    pc_data_relocate();
    pc_audio_init();
    pc_rel_set_module_linker(pc_rel_link, pc_rel_unlink);
    pc_rel_set_resolver(pc_rel_resolve_main); /* modules linked from the disc (common_rel) point into main.dol */
    pc_cms_set_thunks(pc_native_thunks, pc_native_thunk_count); /* script natives called by their C signature */
    pc_room_entered_hook = room_entered;
    OrreHook_WindowReady = (void (*)(u32))pc_pad_script_window_ready;
    {
        /* the autosave's flag watch (pc_autosave.cpp, 2026-11-20: "no story flag changed since the room was entered"),
         * attached here because the hook lives in this file; before the event log, which chains it. Observe only */
        extern void pc_autosave_flag_changed(int flagId, u32 oldValue, u32 newValue);
        OrreHook_FlagChanged = pc_autosave_flag_changed;
    }
    pc_event_log_install(); /* battle text, battle actions and story-flag changes into the log (observe only) */
    pc_ui_inventory_init(); /* ORRE_UI_INVENTORY=1: every 2D piece per room into the log (observe only; widescreen) */
    {
        const char* compat = getenv("ORRE_REPLAY_COMPAT");
        if (compat != NULL && strstr(compat, "cry60") != NULL) {
            OrreHook_OldCryIndex = old_cry_index_on;
            printf("[replay_compat] cry60: the cry screen as before port-gaps 60 (replays of older recordings)\n");
        }
    }
    pc_frame_times_init(); /* ORRE_REPLAY_FRAMES: replay mode plays the console's frame timing (snatcherLeo, 2026-10-18) */
    pc_musyx_push_listener = pc_debug_sound_group_pushed;
    pc_debug_audio_pause = audio_pause; /* the debug toolkit's Pause key also pauses the sound output */
    pc_vi_set_close_ends_program(1);    /* closing the window ends the game, even while it is stuck (pc_vi.c) */
    pc_vi_virtual_clock();              /* replay mode's clock, decided before the game first reads the time */
    pc_card_timing_set_task(&_memcardStatusPtr); /* the memcard task (memcard.c), for console-like card timing */
    if (getenv("ORRE_DUMP_FLAGS") != NULL) {
        s_dump_flags = 1;
        pc_vi_frame_hook = flags_frame;
        atexit(flags_dump);
    }
    atexit(pc_log_drain);
    result = orre_game_main(argc, argv);
    pc_audio_stop();
    pc_platform_stop();
    return result;
}
